// Parses every Electron main/preload module so a syntax error fails fast,
// before the app or the packager loads it.
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const electronDir = join(dirname(dirname(fileURLToPath(import.meta.url))), 'electron');

// nativeBrowserPreload.cjs is generated by `npm run preload:build` and is not in
// git, so a clean checkout would otherwise skip the sandboxed browser preload
// silently and leave this gate passing while checking nothing about it.
const GENERATED_MODULES = ['nativeBrowserPreload.cjs'];
const missing = GENERATED_MODULES.filter((file) => !existsSync(join(electronDir, file)));
if (missing.length > 0) {
  console.error(
    `Electron syntax check is missing generated module(s): ${missing.join(', ')}. ` +
      'Run `npm run preload:build` first.',
  );
  process.exit(1);
}

const files = readdirSync(electronDir)
  .filter((file) => file.endsWith('.cjs') && !file.endsWith('.test.cjs'))
  .sort();

const failures = files.filter((file) => {
  try {
    execFileSync(process.execPath, ['--check', join(electronDir, file)], { stdio: 'inherit' });
    return false;
  } catch {
    return true;
  }
});

if (failures.length > 0) {
  console.error(`Electron syntax check failed: ${failures.join(', ')}`);
  process.exit(1);
}

console.log(`Parsed ${files.length} Electron modules.`);
